# Test hash-based stream generators for payload against candidate known-text signatures
def hashstream(seed, n, fmt):
 out=b""
 i=0
 while len(out)<n:
  if fmt==0: x=hashlib.sha256(seed+i.to_bytes(4,"big")).digest()
