  elif fmt==1: x=hashlib.sha256(seed+i.to_bytes(4,"little")).digest()
  elif fmt==2: x=hashlib.sha256(i.to_bytes(4,"big")+seed).digest()
  elif fmt==3: x=hashlib.sha256(i.to_bytes(8,"big")+seed).digest()
  out+=x; i+=1
