# printable runs
def runs(data,minlen=4):
 out=[]; start=None
 for i,b in enumerate(data+b'\0'):
  if 32<=b<127:
   if start is None:start=i
  else:
   if start is not None and i-start>=minlen:out.append((start,data[start:i]))
   start=None
 return out
runs(hexdata,4)[:80],len(runs(hexdata,4))

