import re, numpy as np
from collections import defaultdict
from fractions import Fraction
rows=[list(map(int,re.search(r'\]\[([^]]*)',l).group(1).split(','))) for l in open('/tmp/fragment/Q5_data.txt')]
ev=defaultdict(list)
for i in range(12,len(rows)):
