 if ch: ev[ch[0]].append(cur[ch[0]-1])

def interp(points, x):
 # Lagrange exact
 out=Fraction(0)
 for i,(xi,yi) in enumerate(points):
  term=Fraction(yi)
  for j,(xj,yj) in enumerate(points):
   if i!=j: term*=Fraction(x-xj,xi-xj)
  out+=term
 return out
